// Un rapport HTML par client, prêt à transférer : c'est la preuve concrète de la valeur de l'abonnement.
const jours = 30, debut = Date.now() - jours * 86400000;
const incidents = $input.all().map(i => i.json).filter(i => new Date(i.horodatage).getTime() >= debut);
const clients = $('Liste des clients').all().map(i => i.json);
const mois = new Date().toLocaleDateString('fr-FR', { month: 'long', year: 'numeric', timeZone: 'Europe/Paris' });
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
return clients.map(c => {
  const mine = incidents.filter(i => i.client === c.client);
  const erreurs = mine.filter(i => i.type === 'erreur');
  const coupures = mine.filter(i => i.type === 'indisponible').length;
  const minutes = mine.filter(i => i.type === 'retablie').reduce((s, i) => s + Number(i.duree_min || 0), 0);
  const dispo = Math.max(0, 100 - minutes / (jours * 1440) * 100).toFixed(2).replace('.', ',');
  const retards = mine.filter(i => i.type === 'retard').length;
  const parWf = Object.entries(erreurs.reduce((m, e) => (m[e.workflow] = (m[e.workflow] || 0) + 1, m), {}))
    .sort((a, b) => b[1] - a[1]).map(([w, n]) => `<li>${esc(w)} : ${n} erreur${n > 1 ? 's' : ''}</li>`).join('') || '<li>Aucune erreur détectée</li>';
  const html = `<div style="font-family:Arial,sans-serif;max-width:680px;color:#23303B">
<h2 style="color:#4A5B6B;margin-bottom:2px">Rapport de maintenance · ${esc(c.client)}</h2>
<p style="margin-top:0;color:#6B7C8C">30 derniers jours · ${mois} · formule ${esc(c.formule || '')}</p>
<table style="border-collapse:collapse;width:100%;margin:14px 0">
<tr><td style="padding:10px;background:#EEF4F7"><b style="font-size:22px">${dispo} %</b><br>disponibilité estimée</td>
<td style="padding:10px;background:#EEF4F7"><b style="font-size:22px">${erreurs.length}</b><br>erreurs détectées</td>
<td style="padding:10px;background:#EEF4F7"><b style="font-size:22px">${coupures}</b><br>interruption${coupures > 1 ? 's' : ''}</td>
<td style="padding:10px;background:#EEF4F7"><b style="font-size:22px">${retards}</b><br>tâche${retards > 1 ? 's' : ''} en retard</td></tr></table>
<h3>Erreurs par automatisation</h3><ul>${parWf}</ul>
<p>Chaque incident a déclenché une alerte immédiate chez votre prestataire de maintenance. <i>[À compléter avant envoi : actions menées et évolutions livrées ce mois-ci.]</i></p>
<p style="color:#8FA3B5;font-size:12px">Disponibilité estimée à partir de contrôles toutes les 5 minutes.</p></div>`;
  return { json: { client: c.client, contact: c.contact, html } };
});
